using Uomd.Contracts;

namespace Uomd.Core
{
    public enum UomdScreenId
    {
        Boot = 0,
        Splash = 1,
        Studio = 2,
        Title = 3,
        Prologue = 4,
        Story = 5,
        Battle = 6,
        Finish = 7,
        Home = 8,
        Chapters = 9,
        Roster = 10,
        Character = 11,
        Gear = 12,
        Team = 13,
        Summon = 14,
        Recruit = 15,
        Shop = 16,
        Tasks = 17,
        Deeds = 18,
        Trials = 19,
