        Mail = 21,
        Library = 22,
        Account = 23,
        Purchases = 24,
        Operations = 25,
        ContentPanel = 26,
        PatchBar = 27
    }

    public sealed class GameSessionState
    {
        public AccountPayloadDto Account { get; set; } = new AccountPayloadDto
        {
            // a signed-out device has no account: balances come only from GET /api/v1/wallet
            playerId = "",
            accountTag = "",
            displayName = "",
            level = 1,
            wallets = new WalletsDto()
        };

        public EntryConfigDto EntryConfig { get; set; } = new EntryConfigDto();
        public PrologueConfigDto PrologueConfig { get; set; } = new PrologueConfigDto();
        public UnityArtExportDto BaseArtSlices { get; set; } = new UnityArtExportDto();
        public BannerInfoDto[] Banners { get; set; } = Array.Empty<BannerInfoDto>();
        public MailItemDto[] MailInbox { get; set; } = Array.Empty<MailItemDto>();

        public string ActiveStorySceneId { get; set; } = "t1_intro";
        /// <summary>Content path of the story scene the Story screen plays next (set by the entry flow).</summary>
        public string ActiveStoryPath { get; set; } = "story/tutorial_t1_before.json";
        /// <summary>A story scene delivered by the server (an Archive reading); when set the Story screen plays it instead of the path.</summary>
        public string ActiveStoryJson { get; set; }
        public string ActiveBattleEncounterId { get; set; } = "tutorial_t1";
        public string SelectedUnitId { get; set; } = "fadyme";
        /// <summary>Gear screen opened from a companion slot: whose slot it fills ("" = the whole armory).</summary>
        public string GearCharacterId { get; set; } = "";
        public string GearSlot { get; set; } = "";
        /// <summary>Where the Recruit (invitations) screen goes back to.</summary>
        public UomdScreenId RecruitReturnTo { get; set; } = UomdScreenId.Home;
        public bool HardModeSelected { get; set; }
        public string BattleHudLayout { get; set; } = "afk_faithful"; // "afk_faithful" | "current" | "arena_lite"
        public bool ReducedMotion { get; set; }
        public bool ReduceFlash { get; set; }

        /// <summary>
        /// Resolves the deterministic first-install / resume entry screen from server account progress
        /// (Studio -> Title -> 9-shot Prologue [no skip on first view] -> T-1/T-2/T-3 -> Finish -> Home/WorldMap).
        /// </summary>
        public UomdScreenId ResolveEntryResumeTarget()
        {
            var prog = Account?.storyProgress;
            if (prog == null || !prog.prologueDone)
            {
                return UomdScreenId.Prologue;
            }

            if (Account.tutorialStep < 3)
            {
                ActiveStorySceneId = Account.tutorialStep switch
                {
                    0 => "t1_intro",
                    1 => "t2_camp",
                    _ => "t3_sanctuary"
                };
                return UomdScreenId.Story;
            }

            return UomdScreenId.Home;
        }

        /// <summary>
        /// Per Prologue first-viewing contract (7207dae1), the SKIP button is hidden on first viewing
        /// (!account.storyProgress.prologueDone) and only shown on subsequent replays.
        /// </summary>
        public bool CanSkipPrologue => Account?.storyProgress != null && Account.storyProgress.prologueDone;
    }
}
